#!/bin/bash
# Render the body of a GitHub Release for one version: the matching CHANGELOG
# section (Chinese first, English folded into <details>) plus the npm dist-tag
# note. CHANGELOG.md is generated by git-cliff, so this is the same text users
# find in the repository — GitHub's own "generate release notes" only knows
# about merged pull requests and comes out empty on this repository's
# direct-to-main history.
#
# Usage:
#   bash scripts/release-notes.sh 0.2.37 > notes.md
#   bash scripts/release-notes.sh "$TAG" | gh release edit "$TAG" --notes-file -
set -euo pipefail

ROOT=$(cd "$(dirname "$0")/.." && pwd)
VERSION="${1:?usage: release-notes.sh <version>}"

PREV="$(git -C "$ROOT" describe --tags --abbrev=0 "v$VERSION^" 2>/dev/null || true)"

# The section of the changelog for one version: everything between its
# `## [version]` heading and the next version heading.
section() {
  awk -v header="## [$1]" '
    index($0, header) == 1 { inside = 1; next }
    inside && /^## \[/ { exit }
    inside { print }
  ' "$2" | sed '/./,$!d'
}

ZH="$(section "$VERSION" "$ROOT/CHANGELOG.md")"
EN="$(section "$VERSION" "$ROOT/CHANGELOG.en.md")"

# A stable tag that only promotes the preceding prerelease carries no commits of
# its own, so git-cliff writes no section for it. Borrow the prerelease's
# section instead of shipping an empty body: this release is exactly that work.
if [[ -z "$ZH$EN" && -n "$PREV" ]]; then
  PREV_VERSION="${PREV#v}"
  ZH="$(section "$PREV_VERSION" "$ROOT/CHANGELOG.md")"
  EN="$(section "$PREV_VERSION" "$ROOT/CHANGELOG.en.md")"
  if [[ -n "$ZH$EN" ]]; then
    printf 'The same changes as %s, now shipped as a stable release.\n\n' "$PREV"
  fi
fi

if [[ -z "$ZH$EN" ]]; then
  ZH="_No changelog entry for v$VERSION._"
fi

printf '%s\n\n' "$ZH"
if [[ -n "$EN" && "$EN" != "$ZH" ]]; then
  printf '<details>\n<summary>English</summary>\n\n%s\n\n</details>\n\n' "$EN"
fi

if [[ "$VERSION" == *-* ]]; then
  DIST="${VERSION#*-}"
  DIST="${DIST%%.*}"
  printf '%s\n\n' "## npm" \
    "This is a prerelease, published under the \`$DIST\` npm dist-tag. \`latest\` keeps pointing at the newest stable release, so \`npm install -g agent-status-indicator\` is unchanged."
else
  printf '%s\n\n' "## npm" \
    "This is a stable release: npm \`latest\` now points to \`$VERSION\`, so \`npm install -g agent-status-indicator\` installs it."
fi

# The compare link GitHub's generated notes used to carry: what changed since
# the previous tag, including the commits git-cliff does not print.
REPO="${REPO:-DuRunzhe/AgentIndicator}"
if [[ -n "$PREV" ]]; then
  printf '**Full Changelog**: https://github.com/%s/compare/%s...v%s\n' "$REPO" "$PREV" "$VERSION"
fi
